// Draw cool-toned fractal spiral
const centerX = W / 2;
const centerY = H / 2;
const radius = Math.min(W, H) * 0.7;

function drawSpiral(ctx, x, y, angle, length, iterations) {
    if (iterations === 0) return;

    // Randomize color slightly
    const hue = (Math.random() + 0.3) * 360;
    ctx.strokeStyle = `hsl(${hue}, 70%, 30%)`;

    // Draw line segment
    ctx.beginPath();
    ctx.moveTo(x, y);
    const newX = x + Math.cos(angle) * length;
    const newY = y - Math.sin(angle) * length;
    ctx.lineTo(newX, newY);
    ctx.stroke();

    // Recursively draw smaller spiral
    drawSpiral(ctx, newX, newY, angle + 0.3, length * 0.75, iterations - 1);
}

